import Foundation

func lowerBounds(_ sequence: [UInt8], _ reverse: FMIndex) -> [Int] { var range = Interval(lower: 0, upper: reverse.size), mismatches = 0, bounds: [Int] = []; for base in sequence { range = reverse.extend(range, base); if range.isEmpty { mismatches += 1; range = Interval(lower: 0, upper: reverse.size) }; bounds.append(mismatches) }; return bounds }
struct SearchState { let position: Int; let remaining: Int; let range: Interval }
struct SearchLeaf { let range: Interval; let mismatches: Int }
struct SearchResult { let nodes: Int; let leaves: [SearchLeaf]; let positions: Int }
func backtrack(_ sequence: [UInt8], _ maximum: Int, _ forward: FMIndex, _ reverse: FMIndex) -> SearchResult { let bounds = lowerBounds(sequence, reverse); var stack = [SearchState(position: sequence.count - 1, remaining: maximum, range: Interval(lower: 0, upper: forward.size))], nodes = 0, leaves: [SearchLeaf] = [], positions = 0; while let state = stack.popLast() { nodes += 1; if state.remaining < (state.position >= 0 ? bounds[state.position] : 0) { continue }; if state.position == -1 { leaves.append(SearchLeaf(range: state.range, mismatches: maximum - state.remaining)); positions += state.range.count; continue }; for base in bases.reversed() { let range = forward.extend(state.range, base); if range.isEmpty { continue }; let mismatch = base == sequence[state.position] ? 0 : 1; if mismatch == 0 || state.remaining >= 1 { stack.append(SearchState(position: state.position - 1, remaining: state.remaining - mismatch, range: range)) } } }; return SearchResult(nodes: nodes, leaves: leaves, positions: positions) }
